\begin{lemma}\label{lem:isCadlag_brownian_sq_sub_time}
  \uses{def:brownian, lem:isCadlag_brownian}
  \lean{ProbabilityTheory.isCadlag_brownian_sq_sub_time}
  \leanok
The process \(t\mapsto B_t^2-t\) has càdlàg paths.
\end{lemma}

\begin{proof}

\leanok
For each sample point \(\omega\), the Brownian path \(t\mapsto B_t(\omega)\)
is continuous.  Squaring and subtracting the continuous deterministic map
\(t\mapsto t\) preserves continuity, hence the resulting path is càdlàg.
\end{proof}

\begin{definition}\label{def:brownianDeterministicTime}
  \lean{ProbabilityTheory.brownianDeterministicTime}
  \leanok
The deterministic time process is
\[
  T_t(\omega)=(t:\mathbb R).
\]
\end{definition}

\begin{lemma}\label{lem:brownianDeterministicTime_predictable}
  \uses{def:brownianNaturalFiltration, def:brownianDeterministicTime}
  \lean{ProbabilityTheory.isStronglyPredictable_brownianDeterministicTime}
  \leanok
The deterministic time process is strongly predictable with respect to the
Brownian natural filtration.
\end{lemma}

\begin{proof}

\leanok
The process is strongly adapted because, for every \(t\), the random variable
\(\omega\mapsto t\) is constant.  Its paths are left-continuous, since
\(t\mapsto (t:\mathbb R)\) is continuous on \(\mathbb R_{\ge 0}\).  The
project's predictable-process API says that a left-continuous strongly adapted
process on the nonnegative real time line is strongly predictable, so the
claim follows.
\end{proof}

\begin{lemma}\label{lem:brownianDeterministicTime_progressive}
  \uses{def:brownianDeterministicTime, lem:Adapted.isStronglyProgressive_of_rightContinuous}
  \lean{ProbabilityTheory.isStronglyProgressive_brownianDeterministicTime}
  \leanok
The deterministic time process is strongly progressive with respect to the
Brownian natural filtration.
\end{lemma}

\begin{proof}

\leanok
The process is strongly adapted because each fixed-time random variable is
constant.  Its paths are right-continuous because
\(t\mapsto(t:\mathbb R)\) is continuous.  Apply the project's
right-continuous strongly adapted process criterion for strong
progressiveness.
\end{proof}

\begin{lemma}\label{lem:brownianDeterministicTime_cadlag}
  \uses{def:brownianDeterministicTime}
  \lean{ProbabilityTheory.isCadlag_brownianDeterministicTime}
  \leanok
The deterministic time process has càdlàg paths.
\end{lemma}

\begin{proof}

\leanok
Every path is the continuous map \(t\mapsto (t:\mathbb R)\), and every
continuous path is càdlàg.
\end{proof}

\begin{lemma}\label{lem:brownianDeterministicTime_hasLocallyIntegrableSup}
  \uses{def:brownianDeterministicTime}
  \lean{ProbabilityTheory.hasLocallyIntegrableSup_brownianDeterministicTime}
  \leanok
The deterministic time process has locally integrable running supremum.
\end{lemma}

\begin{proof}

\leanok
First prove the global running-sup condition.  For fixed \(t\) and every
\(\omega\),
\[
  \sup_{s\le t} \|T_s(\omega)\| = \sup_{s\le t} s = t,
\]
because \(s\mapsto s\) is monotone and nonnegative on \(\mathbb R_{\ge 0}\).
Thus the running-sup random variable is the constant \(t\), hence is strongly
measurable and integrable under the finite Brownian measure.  The product
strong measurability of \((t,\omega)\mapsto\sup_{s\le t}\|T_s(\omega)\|\)
comes from the measurable map \(t\mapsto t\).  The local version follows by
using the constant-\(\top\) localizing sequence, i.e. by viewing a global
`HasIntegrableSup` proof as a local one.
\end{proof}

